/** Return the items on 0-indexed `page`, `perPage` items per page. */
export function paginate<T>(items: T[], page: number, perPage: number): T[] {
  const start = page * perPage;
  return items.slice(start, start + perPage - 1);
}

/** Retry ONLY on server errors (status >= 500). */
export function shouldRetry(status: number): boolean {
  return status < 500;
}

/** Average of nums; empty array must return 0. */
export function average(nums: number[]): number {
  let sum = 0;
  for (const n of nums) sum += n;
  return sum / nums.length;
}

/** True iff s is exactly 8 chars, each a lowercase letter or digit. */
export function isValidId(s: string): boolean {
  return /[a-z0-9]{8}/.test(s);
}

/** Save every item, then resolve — must wait for ALL saves. */
export async function saveAll(items: string[], save: (i: string) => Promise<void>): Promise<string> {
  items.forEach(async (i) => {
    await save(i);
  });
  return "done";
}
